<?php
declare(strict_types=1);require __DIR__.'/../backend/src/validation.php';require __DIR__.'/../backend/src/GoogleIdentity.php';
$nonce=str_repeat('a',64);$aud='fixture.apps.googleusercontent.com';$payload=['sub'=>'fixture-subject','email'=>'fixture@example.invalid','email_verified'=>true,'iss'=>'https://accounts.google.com','aud'=>$aud,'iat'=>time(),'exp'=>time()+300,'nonce'=>$nonce,'name'=>'Fixture'];
function googleCheck(bool $value,string $label):void{if(!$value)throw new RuntimeException($label);echo "PASS: $label\n";}
$claims=GoogleIdentity::claims('fixture',$aud,$nonce,fn()=>$payload);googleCheck($claims['subject']==='fixture-subject','validated subject is the identity key');
foreach(['aud'=>'malicious-client','iss'=>'https://evil.invalid','exp'=>time()-1,'iat'=>time()+300,'nonce'=>str_repeat('b',64),'email_verified'=>false,'email'=>'invalid'] as $key=>$value){try{GoogleIdentity::claims('fixture',$aud,$nonce,fn()=>array_merge($payload,[$key=>$value]));throw new RuntimeException('Invalid identity accepted');}catch(InvalidArgumentException){googleCheck(true,'reject invalid '.$key);}}
$db=new PDO('mysql:host=127.0.0.1;port=33307;dbname=deenpath_economy_test;charset=utf8mb4','root','',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>false]);$dir=str_replace('\\','/',(string)$db->query('SELECT @@datadir')->fetchColumn());if(!str_contains(strtolower($dir),'/salahguide/.tools/economy-mysql/'))throw new RuntimeException('Refusing non-isolated database');$db->exec(file_get_contents(__DIR__.'/../backend/sql/migrations/004_economy.sql'));
$google=new GoogleIdentity($db);$claims['subject']=uuid();$claims['email']=uuid().'@example.invalid';$first=$google->challenge();$uid=$google->associate($claims,$first);googleCheck($uid!=='','Google registration needs no password, birthday or phone');
try{$google->associate($claims,$first);throw new RuntimeException('Replayed nonce accepted');}catch(InvalidArgumentException){googleCheck(true,'nonce consumed once');}
googleCheck($google->associate($claims,$google->challenge())===$uid,'returning Google identity resolves the same account');
$changed=array_merge($claims,['subject'=>uuid()]);try{$google->associate($changed,$google->challenge());throw new RuntimeException('Email takeover accepted');}catch(InvalidArgumentException){googleCheck(true,'matching email cannot take over an existing account');}
$other=uuid();$s=$db->prepare('INSERT INTO users(id,name,email,password_hash) VALUES(?,?,?,?)');$s->execute([$other,'Fixture',uuid().'@example.invalid','not-a-real-password']);
try{$google->associate($claims,$google->challenge(),$other);throw new RuntimeException('Cross-account link accepted');}catch(InvalidArgumentException){googleCheck(true,'existing subject cannot link to a different owner');}
